// One dated row per question: is the brand named, where among the brands ChatGPT lists, is the site cited.
const s = $('Settings').first().json;
const brand = String(s.brand || '').trim().toLowerCase();
const site = String(s.website || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const competitors = String(s.competitors || '').split(',').map((c) => c.trim()).filter(Boolean);
const date = new Date().toISOString().slice(0, 10);
const named = (text, name) => !!name && new RegExp('(^|[^\\p{L}\\p{N}])' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^\\p{L}\\p{N}])', 'iu').test(text);
const onSite = (d) => !!site && (d === site || String(d).endsWith('.' + site));
return $input.all().filter(({ json: r }) => r.found).map(({ json: r }) => {
  const answer = r.answer || '';
  const brands = (r.brandEntities || []).map((e) => e.name || e.title || '');
  const brandRank = brands.findIndex((b) => named(b, brand) || named(brand, b.toLowerCase()));
  const cited = r.citedDomains || [];
  const siteRank = cited.findIndex(onSite);
  return { json: {
    date,
    question: r.prompt,
    brandNamed: named(answer, brand),
    brandRank: brandRank >= 0 ? brandRank + 1 : null,
    brandsListed: brands.length,
    siteCited: siteRank >= 0,
    siteCitationRank: siteRank >= 0 ? siteRank + 1 : null,
    competitorsNamed: competitors.filter((c) => named(answer, c)).join(', '),
    topCitedDomains: cited.slice(0, 5).join(', '),
    chatgptUrl: r.chatgptUrl,
  } };
});
